 const oldCurrent=prepare(currentRaw),oldPrevious=prepare(previousRaw),record=oldCurrent?.record||{snapshot:validateSnapshot(blank()),attachments:[]};const allFiles=[...(oldCurrent?.files||[]),...(oldPrevious?.files||[])],allRefs=[...record.attachments,...(oldPrevious?.record.attachments||[])];let job;
