 function log(c,text){c.snapshot.events.unshift({date:new Date().toISOString(),text})}
 async function createExport({expectedVersion,key='current'}={}){const record=await readRecord(key);if(!record)fail('NOT_FOUND','Архив отсутствует');if(expectedVersion!==undefined&&record.snapshot.version!==expectedVersion)fail('STALE','Архив изменился');const id=randomId(),now=Date.now(),job={id,kind:'export',snapshot:clone(record.snapshot),refs:clone(record.attachments),createdAt:now,touchedAt:now};try{await transact('readwrite',['metadata','sessions'],(s,w)=>w(s.metadata.get(key),latest=>{if(!latest||latest.snapshot.version!==record.snapshot.version)fail('STALE','Архив изменился');w(s.sessions.get(id),exists=>{if(exists)fail('VALIDATION','Повтор ID операции');w(s.sessions.put(job,id))})}));}catch(e){if(e?.name!=='QuotaExceededError')throw e;fallbackExports.set(id,{key,record:toMeta(record)})}return {exportId:id,snapshot:clone(record.snapshot),files:filesFor(record).map(({payloadId,...f})=>f),chunkBytes:CHUNK_BYTES}}
