 async function getAttachment(revisionId){const current=await readRecord(),r=current?.snapshot.revisions.find(x=>x.id===revisionId);if(!r)fail('NOT_FOUND','Редакция отсутствует');if(!r.attachment)return null;const exported=await createExport({expectedVersion:current.snapshot.version});try{const file=exported.files.find(f=>f.revisionId===revisionId),parts=[],h=new Sha256();for(let i=0;i<file.chunkCount;i++){const bytes=await readExportChunk({exportId:exported.exportId,revisionId,index:i});h.update(new Uint8Array(bytes));parts.push(bytes);await pause()}if(h.digestHex()!==file.sha256)fail('VALIDATION','Контрольная сумма файла не совпала');return {...r.attachment,blob:new Blob(parts,{type:r.attachment.type})}}finally{await endExport({exportId:exported.exportId}).catch(()=>{})}}
