 async function restorePrevious({expectedVersion,onProgress,signal}){const c=context('Восстановление снимка',onProgress,signal),exported=await createExport({key:'previous'});try{const record=await readRecord('previous');if(!record||record.snapshot.version!==exported.snapshot.version)fail('STALE','Снимок изменился');let n=0;for(const file of exported.files){progress(onProgress,'hash',n++,exported.files.length);if(await hashPayload(file,c,i=>readExportChunk({exportId:exported.exportId,revisionId:file.revisionId,index:i}))!==file.sha256)fail('VALIDATION','Снимок повреждён')}log(record,'Восстановлен предыдущий снимок архива');progress(onProgress,'write',0,1);const snapshot=await commit(record,expectedVersion,true,c);progress(onProgress,'write',1,1);return snapshot}finally{await endExport({exportId:exported.exportId}).catch(()=>{})}}
 async function base64(bytes,c){const parts=[];for(let i=0;i<bytes.length;i+=196608){checkOperation(c);let binary='';const end=Math.min(i+196608,bytes.length);for(let j=i;j<end;j+=8192)binary+=String.fromCharCode(...bytes.subarray(j,Math.min(j+8192,end)));parts.push(btoa(binary));await pause()}return parts.join('')}
